class Solution:
    def minCost(self, n: int, edges: List[List[int]]) -> int:
        adj = [[] for _ in range(n)]
        for u, v, w in edges:
            adj[u].append((v, w)); adj[v].append((u, w))
        best = float('inf')
        seen = [False] * n
        def dfs(u, s, m):
            nonlocal best
            if u == n - 1:
                best = min(best, s - m)
                return
            for v, w in adj[u]:
                if not seen[v]:
                    seen[v] = True
                    dfs(v, s + w, max(m, w))
                    seen[v] = False
        seen[0] = True
        dfs(0, 0, 0)
        return best

