class Solution {
public:
    int minCost(int n, vector<vector<int>>& edges) {
        vector<vector<pair<int,int>>> adj(n);
        for (auto& e : edges) { adj[e[0]].push_back({e[1], e[2]}); adj[e[1]].push_back({e[0], e[2]}); }
        long long best = LLONG_MAX;
        vector<char> seen(n, 0);
        function<void(int,long long,long long)> dfs = [&](int u, long long s, long long m) {
            if (u == n - 1) { best = min(best, s - m); return; }
            for (auto [v, w] : adj[u]) if (!seen[v]) {
                seen[v] = 1; dfs(v, s + w, max(m, (long long)w)); seen[v] = 0;
            }
        };
        seen[0] = 1; dfs(0, 0, 0);
        return (int)best;
    }
};

