class Solution {
    long best = Long.MAX_VALUE;
    boolean[] seen;
    List<List<int[]>> adj;
    public int minCost(int n, int[][] edges) {
        adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) { adj.get(e[0]).add(new int[]{e[1], e[2]}); adj.get(e[1]).add(new int[]{e[0], e[2]}); }
        seen = new boolean[n];
        seen[0] = true;
        dfs(0, 0, 0);
        return (int) best;
    }
    void dfs(int u, long s, long m) {
        if (u == adj.size() - 1) { best = Math.min(best, s - m); return; }
        for (int[] vw : adj.get(u)) if (!seen[vw[0]]) {
            seen[vw[0]] = true; dfs(vw[0], s + vw[1], Math.max(m, vw[1])); seen[vw[0]] = false;
        }
    }
}

