class Solution:
    def minCost(self, n: int, edges: List[List[int]]) -> int:
        import heapq
        adj = [[] for _ in range(n)]
        for u, v, w in edges:
            adj[u].append((v, w)); adj[v].append((u, w))
        INF = float('inf')
        def dij(src):
            d = [INF] * n
            d[src] = 0
            pq = [(0, src)]
            while pq:
                du, u = heapq.heappop(pq)
                if du > d[u]:
                    continue
                for v, w in adj[u]:
                    nd = du + w
                    if nd < d[v]:
                        d[v] = nd
                        heapq.heappush(pq, (nd, v))
            return d
        d0 = dij(0)
        d1 = dij(n - 1)
        ans = INF
        for u, v, w in edges:
            if d0[u] < INF and d1[v] < INF:
                ans = min(ans, d0[u] + d1[v])
        return ans

