class Solution {
public:
    int minCost(int n, vector<vector<int>>& edges) {
        vector<vector<pair<int,int>>> adj(n);
        for (auto& e : edges) { adj[e[0]].push_back({e[1], e[2]}); adj[e[1]].push_back({e[0], e[2]}); }
        const long long INF = LLONG_MAX / 4;
        auto dij = [&](int src) {
            vector<long long> d(n, INF);
            priority_queue<pair<long long,int>, vector<pair<long long,int>>, greater<>> pq;
            d[src] = 0; pq.push({0, src});
            while (!pq.empty()) {
                auto [du, u] = pq.top(); pq.pop();
                if (du > d[u]) continue;
                for (auto [v, w] : adj[u]) if (du + w < d[v]) {
                    d[v] = du + w; pq.push({d[v], v});
                }
            }
            return d;
        };
        auto d0 = dij(0), d1 = dij(n - 1);
        long long ans = INF;
        for (auto& e : edges)
            if (d0[e[0]] < INF && d1[e[1]] < INF)
                ans = min(ans, d0[e[0]] + d1[e[1]]);
        return (int)ans;
    }
};

