class Solution {
    public int minCost(int n, int[][] edges) {
        List<List<long[]>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) { adj.get(e[0]).add(new long[]{e[1], e[2]}); adj.get(e[1]).add(new long[]{e[0], e[2]}); }
        long INF = Long.MAX_VALUE / 4;
        java.util.function.IntFunction<long[]> dij = src -> {
            long[] d = new long[n]; Arrays.fill(d, INF);
            PriorityQueue<long[]> pq = new PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));
            d[src] = 0; pq.add(new long[]{0, src});
            while (!pq.isEmpty()) {
                long[] top = pq.poll();
                int u = (int) top[1];
                if (top[0] > d[u]) continue;
                for (long[] vw : adj.get(u)) if (top[0] + vw[1] < d[(int) vw[0]]) {
                    d[(int) vw[0]] = top[0] + vw[1];
                    pq.add(new long[]{d[(int) vw[0]], vw[0]});
                }
            }
            return d;
        };
        long[] d0 = dij.apply(0), d1 = dij.apply(n - 1);
        long ans = INF;
        for (int[] e : edges)
            if (d0[e[0]] < INF && d1[e[1]] < INF)
                ans = Math.min(ans, d0[e[0]] + d1[e[1]]);
        return (int) ans;
    }
}

