    const d0 = dij(0), d1 = dij(n - 1);
    let ans = INF;
    for (const [u, v, w] of edges)
        if (d0[u] < INF && d1[v] < INF)
            ans = Math.min(ans, d0[u] + d1[v]);
    return ans;
};
